        ls.appendChild(make('span', 'sp-rr-ll', r.sub.label || ''));
        if (sub && sub.landedOf && sub.landedOf !== 'the only one') ls.appendChild(make('i', 'sp-rr-lof', sub.landedOf));
        line.appendChild(ls);
